  @tag court: "CHI-POST"
  @tag falsifier: "CHI-POST-005"
  test "CHI-POST-005 positive control: granted, admitted, committed, row visible", %{
    store_opts: store_opts,
    broker: broker,
    grant: grant,
    command: command,
    command_bus: command_bus,
    identity: identity,
    message: message,
    part: part
  } do
    label = unique_label()
    subject = identity.principal(@principal)

    # Real standing grant through the real broker.
    {:ok, _authority} = grant.grant(subject, @capability, broker: broker)

    # Real authority decision on the dispatch path.
    authority = grant.authorize(@principal, @capability, policy: :broker, broker: broker)

    command_record =
      command.new(@capability,
        command_id: "chicago-pack-#{System.unique_integer([:positive])}",
        agent_id: "chicago-pack-agent",
        principal_id: @principal,
        authority: authority,
        input: %{@post_attribute => label}
      )

    wire_message = message.new_user([part.new(%{@post_attribute => label})])

    reply =
      command_bus.run(command_record, wire_message, @resource,
        store: @receipt_store,
        store_opts: store_opts
      )

    assert {:ok, receipt} = reply
    assert receipt.status == :completed

    # Independent post-state read: the actuator is not the attestor of its own
    # success.
    assert row_present?(label)
  end



